from typing import Any, List
from parser import parse_path

def query_json(data: Any, path_expr: str) -> Any:
    segments = parse_path(path_expr)
    current = data

    for seg in segments:
        if current is None:
            return None

        if seg.is_wildcard:
            if isinstance(current, dict):
                # Bug: returns list of keys instead of list of values
                current = list(current.keys())
            elif isinstance(current, list):
                current = current
            else:
                return None
        else:
            if isinstance(current, dict):
                current = current.get(seg.key)
            elif isinstance(current, list):
                current = [item.get(seg.key) for item in current if isinstance(item, dict) and seg.key in item]
            else:
                return None

            if seg.index is not None and isinstance(current, list):
                if 0 <= seg.index < len(current):
                    current = current[seg.index]
                elif -len(current) <= seg.index < 0:
                    current = current[seg.index]
                else:
                    return None

    return current

tests.test_evaluator.py:
from evaluator import query_json

def test_simple_dot_path():
    data = {"user": {"profile": {"name": "Alice"}}}
    assert query_json(data, "user.profile.name") == "Alice"

def test_wildcard_object_values():
    data = {
        "users": {
            "u1": {"age": 30, "role": "admin"},
            "u2": {"age": 25, "role": "user"},
        }
    }
    roles = query_json(data, "users.*.role")
    assert sorted(roles) == ["admin", "user"]

def test_array_indexing():
    data = {"scores": [10, 20, 30]}
    assert query_json(data, "scores[0]") == 10
    assert query_json(data, "scores[-1]") == 30

